// ************
// Types
// ************

import '@dev.hiconic/gm_root-model';
import '@dev.hiconic/gm_resource-model';
import '@dev.hiconic/gm_i18n-model';
import '@dev.hiconic/gm_icon-model';
import '@dev.hiconic/gm_gm-core-api';

import { T } from '@dev.hiconic/hc-js-base';

export declare namespace meta {
	const groupId: string;
	const artifactId: string;
	const version: string;
}

export import AuthEntity = T.com.braintribe.model.user.AuthEntity;
export import Group = T.com.braintribe.model.user.Group;
export import Identity = T.com.braintribe.model.user.Identity;
export import Role = T.com.braintribe.model.user.Role;
export import User = T.com.braintribe.model.user.User;

declare module '@dev.hiconic/hc-js-base' {

	namespace T.com.braintribe.model.user {

		const AuthEntity: hc.reflection.EntityType<AuthEntity>;
		type AuthEntity = T.com.braintribe.model.descriptive.HasName &
		  Entity<"com.braintribe.model.user.AuthEntity">;

		const Group: hc.reflection.EntityType<Group>;
		type Group = Identity &
		  Entity<"com.braintribe.model.user.Group", {
			conflictPriority: P<double, { nullable: false }>;
			localizedName: T.com.braintribe.model.generic.i18n.LocalizedString;
			users: set<User>;
		}>;

		const Identity: hc.reflection.EntityType<Identity>;
		type Identity = T.com.braintribe.model.generic.StandardStringIdentifiable & AuthEntity &
		  Entity<"com.braintribe.model.user.Identity", {
			description: T.com.braintribe.model.generic.i18n.LocalizedString;
			email: string;
			picture: T.com.braintribe.model.resource.Icon;
			roles: set<Role>;
		}>;

		const Role: hc.reflection.EntityType<Role>;
		type Role = T.com.braintribe.model.generic.StandardStringIdentifiable & AuthEntity &
		  Entity<"com.braintribe.model.user.Role", {
			description: T.com.braintribe.model.generic.i18n.LocalizedString;
			localizedName: T.com.braintribe.model.generic.i18n.LocalizedString;
		}>;

		const User: hc.reflection.EntityType<User>;
		type User = Identity & T.com.braintribe.model.descriptive.HasPassword &
		  Entity<"com.braintribe.model.user.User", {
			firstName: string;
			groups: set<Group>;
			lastLogin: date;
			lastName: string;
		}>;

	}

}
